examples.template:
MonarchAiSummaryCard(
    {{title}},
    summary: {{summary}},
    generatedAt: {{generatedAt|date}},
    now: {{now|date}},
    sources: [
        MonarchAiSourcePart(id: {{sources.0.id}}, title: {{sources.0.title}}, url: {{sources.0.url}}, kind: {{sources.0.kind|case}}),
        MonarchAiSourcePart(id: {{sources.1.id}}, title: {{sources.1.title}}, kind: {{sources.1.kind|case}}, product: {{sources.1.product}}),
    ],
    onRefresh: {}
) {
    MonarchButton({{actionLabel}}, variant: .ghost, size: .sm) {}
}

examples.code:
MonarchAiSummaryCard(
    "Account summary",
    summary: "The customer renewed for another year in **January** and added two seats.\n\n- Usage is steady at about 40 active people a week.\n- One open support ticket about exports.",
    generatedAt: Date(timeIntervalSince1970: 1_795_003_200),
    now: Date(timeIntervalSince1970: 1_795_014_000),
    sources: [
        MonarchAiSourcePart(id: "notes", title: "Renewal call notes", url: "https://example.com/notes/renewal", kind: .doc),
        MonarchAiSourcePart(id: "ticket", title: "Ticket 2041: CSV export", kind: .record, product: "Support"),
    ],
    onRefresh: {}
) {
    MonarchButton("Open in assistant", variant: .ghost, size: .sm) {}
}

MonarchAiSummaryCard(
    "Ticket summary",
    summary: "Most questions were about invoices.",
    status: .stale,
    onRefresh: {}
) {
    Button("Copy") {}.buttonStyle(.monarch(.ghost, size: .sm))
}
